module.exports = async function (data) {
  const p = { ...(data.$trigger?.payload ?? {}) };
  const coll = data.$trigger?.collection;
  const source = coll === 'categories' ? p.name : p.title;
  if (!source) return p;
  p.slug = String(source)
    .toLowerCase()
    .replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9]+/g,'-')
    .replace(/^-+|-+$/g,'');
  return p;
};

module.exports = async function (data) {
  const p = { ...(data.$trigger?.payload ?? {}) };
  const touches = 'start_date' in p || 'show_days_before' in p;
  if (!touches) return p;
  if ('start_date' in p && !p.start_date) { p.visible_from = null; return p; }
  if (p.start_date) {
    const days = Number(p.show_days_before ?? 0) || 0;
    const dt = new Date(p.start_date);
    dt.setDate(dt.getDate() - days);
    p.visible_from = dt.toISOString();
  }
  return p;
};
